def rule(id,title,state,sids,req,trigger,deadline=None,exceptions='An exemption must be checked against its conditions; no exemption is approved by this record.',fee=None,status='verified',limits=None,renewal=None,topic='sales-disclosure'):
 r=dict(id=id,title=title,topic=topic,jurisdiction=state,activity='Offering or selling a partner-operated business model',affectedParty='Franchisor / subfranchisor and responsible sales manager',applicability='Where the relevant state franchise law applies to the transaction; evaluate the parties, offer, residence, locations and model.',requirement=req,exceptions=exceptions,trigger=trigger,deadline=deadline,fee=None if fee is None else dict(value=fee,currency='USD',asOf=today),renewal=renewal,dependencies=['Relationship factsheet','Jurisdiction and offer-location review'],evidence=['Dated disclosure and agreement versions','Filing acknowledgement or documented exemption analysis','Named responsible person'],sourceIds=['state-'+s for s in sids],status=status,legalStatus='effective',verifiedAt=today,nextReview='2026-12-12',conflicts=[],interpretationLimits=limits or ['This record covers the stated issue, not all applicable laws, sector requirements or local permissions.'],dependentPaths=[],reviewerStatus=review);rules.append(r);return id
rule('tx-franchise-exemption-notice','Texas FTC-compliant franchise exemption notice','Texas',['tx-faq'],'The Secretary of State describes a business-opportunity registration exemption for franchisors complying in all material respects with applicable FTC disclosure requirements and prohibitions in Texas. The seller must file the exemption notice before offering or selling.','Before offering for sale or selling','Before first covered offer or sale',fee=25,renewal='The FAQ describes a one-time notice without expiry, with written notice of principal-address changes.')
rule('wa-registration','Washington registration and exemption analysis','Washington',['wa-law','wa-franchise'],'RCW 19.100.020 prohibits covered offers or sales unless the offering is registered or exempt. Registration and exemption are distinct from federal disclosure.','Before covered offer or sale','Before covered offer or sale')
rule('wa-disclosure-changes','Washington initial disclosure and revised agreements','Washington',['wa-law'],'RCW 19.100.080 provides a 14-calendar-day disclosure period and a separate seven-calendar-day period for unilaterally material agreement changes; prospect-initiated negotiations are treated separately.','Planned binding agreement, payment or material agreement revision','14 calendar days for disclosure; 7 calendar days for the specified revised agreements',exceptions='The statute excludes changes arising from negotiations initiated by the prospective franchisee from the seven-day agreement-change period.')
rule('wa-advertising','Washington prepublication franchise advertising filing','Washington',['wa-law'],'A true copy of advertising offering a franchise subject to registration must be filed at least seven days before publication, unless a shorter period is allowed by rule or order.','Planned publication of covered franchise advertising','At least 7 days before publication',exceptions='Scope depends on the registration requirement and any applicable rule or order.')
rule('wa-relationship','Washington ongoing relationship protections','Washington',['wa-law'],'RCW 19.100.180 includes good-faith duties and restrictions involving purchasing, territory, termination and renewal. Contract wording does not alone establish enforceability.','Drafting or changing the agreement; supplier, territory, termination or renewal decisions',topic='relationship')
rule('va-registration','Virginia registration or applicable exemption','Virginia',['va-franchise'],'Franchises offered or sold in Virginia must be registered or exempt. Some exemptions require a filing before an offer or sale.','Before covered offer or sale','Before covered offer or sale')
rule('or-disclosure','Oregon disclosure without pre-sale franchise filing approval','Oregon',['or-franchise'],'Oregon DFR says franchisors must give disclosure at least 14 days before a contract or payment and retain complete books, records and franchise-sale details. Oregon does not require filing franchise documents and obtaining approval before a sale.','Planned franchise contract or receipt of money','At least 14 days before signing or payment',exceptions='This says nothing about separate business-opportunity, sector, entity, employment or local duties.')
rule('ny-renewal','New York fiscal-year-based franchise renewal','New York',['ny-guide'],'The Attorney General directs annual renewal submissions within 120 days after fiscal year end. If registration expires, covered offers or sales within or from New York must stop until renewal is submitted and accepted for filing.','Franchisor fiscal year end','Within 120 days after fiscal year end',renewal='Annual fiscal-year-based renewal; separately monitor prompt material-change amendments.')
rule('ny-advertising','New York franchise advertising submission','New York',['ny-guide'],'Submit two copies of advertising to be used in offering or selling franchises via NASAA FRED at least seven days before intended use.','Planned franchise advertising','At least 7 days before intended use')
rule('wi-registration','Wisconsin registration is not merit approval','Wisconsin',['wi-faq','wi-filing'],'The agency states registration is due no later than the first Wisconsin franchise sale, is effective on receipt, lasts one year, and is not merit review. Each franchise system requires a separate registration and fee.','First Wisconsin sale; expiry of existing registration','No later than first sale; avoid a sales gap after expiry',fee=400,renewal='New annual registration before expiry; not a continuing merit approval.')
rule('wi-amendment','Wisconsin material-event amendment','Wisconsin',['wi-faq'],'A registrant must amend within 30 days of a material event; the amendment is effective on receipt and does not extend the original registration period.','A material event','Within 30 days',fee=200)
rule('wi-disclosure','Wisconsin disclosure timing','Wisconsin',['wi-faq'],'Provide the FDD 14 calendar days before the earlier of signing a binding franchise or other agreement or paying consideration. The agency says franchise advertising need not be filed.','Planned binding agreement or payment','14 calendar days before the earlier event')
rule('mn-registration','Minnesota registration before offer or sale','Minnesota',['mn-law','mn-register'],'A covered franchise offer or sale requires an effective registration unless the transaction or franchise is exempt under section 80C.03. The Department uses ComOnline for filings.','Before covered offer or sale','Before covered offer or sale',renewal='Registration effective for 12 months from the commissioner order; calendar reporting and renewal work separately.')
rule('mn-assurance','Minnesota financial assurance changes fee availability','Minnesota',['mn-assurance'],'Where adequate financial arrangements have not been demonstrated, the commissioner may require escrow, impoundment or deferral. The published guidance describes a surety bond alternative and fee deferral until the franchisee opens.','Financial review during registration; planning cash available for support',exceptions='The selected financial condition and release requirements depend on the actual review and terms, not a universal cash threshold.')
rule('hi-filing','Hawaii filing-document consistency','Hawaii',['hi-filings','hi-tips'],'Hawaii directs electronic portal submission. Its filing tips call for consistent FDD and form data, U.S.-notarized Form C, and an auditor consent referencing the correct statements and guarantor where relevant.','Preparing initial, renewal or amended franchise filing',exceptions='Confirm the current forms, portal instructions and any applicable financial-statement order before filing.')
rule('il-forms','Illinois franchise application and financial-assurance documents','Illinois',['il-info'],'The Attorney General administers franchise registration and publishes application, costs/source-of-funds, seller, accountant-consent, escrow, guaranty and surety-bond forms. A form being available does not make it mandatory in every application.','Preparing an Illinois filing or responding to financial review',status='conditional',limits=['The initial timing rule, exemption tests and relationship provisions require a separate current statutory review. No filing fee or effectiveness date is asserted here.'])
rule('md-registration','Maryland franchise offer registration','Maryland',['md-statute'],'Section 14-214 requires registration before offering through advertisement or otherwise, or selling in the state, subject to its stated exclusions and exemptions.','Before covered offer including advertising','Before covered offer or sale')
rule('md-advertising','Maryland advertising review','Maryland',['md-rules'],'COMAR 02.02.08.09 requires covered franchise advertising submitted at least five days before anticipated initial use.','Planned initial use of advertising for an offering subject to registration','At least 5 days before anticipated initial use')
rule('md-exempt-disclosure','Maryland exemption does not automatically remove disclosure','Maryland',['md-rules'],'COMAR 02.02.08.10 describes specified exemptions with notice conditions and a separate disclosure rule. For exemptions in D–G, absent a contrary order, disclosure and proposed agreements are due at the earlier of the first personal meeting or ten business days before signing/payment.','Claiming one of the specified exemptions; first personal meeting; agreement or payment','For specified D–G exemptions: earlier of first personal meeting or 10 business days before signing/payment',status='conditional',limits=['The rule uses legacy UFOC terminology and references; coordinate it with current agency filing directions and the federal Rule. Do not replace the earlier meeting trigger with a generic 14-day statement.','Exact exemption selection and transaction applicability remain fact-specific.'])
rule('mi-notice','Michigan annual notice of intent','Michigan',['mi-notice','mi-info'],'File the annual notice before offering or selling. The agency describes a $250 fee and makes clear it does not review FDDs for compliance.','Before covered offer or sale','Before covered offer or sale',fee=250,renewal='Annually; notice effective for one year from filing.')
rule('mi-disclosure','Michigan business-day disclosure period','Michigan',['mi-disclosure'],'Section 445.1508 requires disclosure, the Michigan notice and proposed agreements at least ten business days before binding agreement or consideration, whichever comes first. Keep the federal calendar-day requirement as a separate clock.','Planned agreement or receipt of consideration','At least 10 business days before earlier event')
rule('in-notification','Indiana registration by notification','Indiana',['in-info'],'Register before a covered offer or sale unless exempt. Indiana describes registration as notice filing without merit review, initial effectiveness upon receipt if no stop order applies, and one-year registration.','Before covered offer or sale','Before covered offer or sale',fee=500,renewal='One year; renewal due no later than expiry. A lapse requires an initial filing and fee.')
rule('nd-renewal','North Dakota franchise renewal and current addendum practice','North Dakota',['nd-info'],'The Department directs renewal no later than 15 business days before expiry unless waived. Its current page states that as of April 1, 2026 a state-specific FDD addendum is no longer required; other registration and disclosure obligations continue.','Preparing North Dakota initial/renewal filings; expiry planning','Renewal at least 15 business days before expiry unless waived',renewal='Generally 12 months from effective date unless specified otherwise by order or rule.')
rule('ri-registration','Rhode Island registration and annual duration','Rhode Island',['ri-law','ri-rule'],'Covered offers or sales require registration or exemption. The active regulation says registration expires 365 calendar days after its initial effective date; exemption notices have their own 365-day period measured from receipt.','Before covered offer or sale; registration or notice anniversary','Before covered offer or sale; calendar the correct anniversary',renewal='Annual; effective-date and notice-receipt anniversaries differ.')
rule('sd-notice','South Dakota franchise notice filing','South Dakota',['sd-notice','sd-duration','sd-info'],'A covered offer or sale requires proper notice filing unless exempt. The statute describes a complete filing, FDD, consent and initial $250 fee; effectiveness is generally on receipt subject to orders and completeness provisions.','Before covered offer or sale','Before covered offer or sale',fee=250,renewal='One year from initial application receipt unless a different period is prescribed; renewal $150; late filing treated as initial.')
rule('sd-advertising','South Dakota advertising and going-concern changes','South Dakota',['sd-ads','sd-duration'],'Advertising filing is not required unless requested by the director, but false or misleading advertising can be barred by written order. After notice effectiveness, an auditor going-concern conclusion must be notified within 15 days.','Advertising review; auditor concludes substantial doubt about continuing as a going concern','Going concern: within 15 days after auditor conclusion',exceptions='No routine advertising filing is not permission to make unsubstantiated claims.')
