def guide(slug,title,description,ruleids,sections,output,limitations=None,family='state',path=None):
 rr=[r for r in rules if r['id'] in ruleids];jur=sorted({r['jurisdiction'] for r in rr});sids=sorted({s for r in rr for s in r['sourceIds']});p=path or '/states/'+slug+'/'
 g=dict(id='state-guide-'+slug,path=p,title=title,description=description,family=family,topic='sales-disclosure',jurisdictions=jur,status='published',lastReviewed=today,reviewStatus=review,readMinutes=max(3,round(sum(len(' '.join(s.get('paragraphs',[])+s.get('bullets',[])).split()) for s in sections)/180)),ruleIds=ruleids,sections=sections,sourceIds=sids,nextStage=1,practicalOutput=output,limitations=limitations or ['This guide reviews the stated franchise issue. Corporate tax, employment, operating permits and address-dependent requirements are separate research tasks.','No transaction-specific legal review has taken place. Record the offer locations, parties, model and planned dates before applying an exemption.']);guides.append(g)
 for r in rr:r['dependentPaths'].append(p)
def sec(h,*p,bullets=None,table=None):
 x=dict(heading=h,paragraphs=list(p))
 if bullets:x['bullets']=bullets
 if table:x['table']=table
 return x
guide('texas','Texas: the franchise exemption still needs a pre-offer notice','A qualifying FTC-compliant franchisor can be exempt from Texas business-opportunity registration, but the notice comes before an offer or sale.',['tx-franchise-exemption-notice'],[
sec('The exemption and the notice are separate','Texas Secretary of State FAQ 5 describes an exemption from business-opportunity registration where a franchisor complies in all material respects in Texas with applicable Federal Trade Commission disclosure requirements and prohibitions. The same answer requires an exemption notice before offering for sale or selling. An overseas parent should not treat federal disclosure preparation as the Texas filing.'),
sec('What the company secretary should prepare','Form 2703 asks for the franchisor’s legal name, all names under which it does or intends to do business, and principal business address. The FAQ lists a $25 fee. Its one-time notice has no expiry, but principal-address changes should be notified in writing.',bullets=['Identify the entity actually selling the rights; do not substitute the parent merely because it owns the trademark.','Map the planned prospect communications and Texas connections for review.','Record why the federal-compliance condition is satisfied and preserve the filed notice.']),
sec('Fictional example: a Singapore facilities brand','The brand has a completed FDD and schedules a Texas partner campaign. Its sales manager marks “Texas filing not needed” because the business calls the arrangement a licence. The corrected task is to establish the relationship facts, review the relevant offer and exemption, and file the applicable notice before the covered campaign. Renaming the contract does not establish the exemption.'),
sec('Do not confuse two filing tracks','The FAQ also describes registration, disclosures and update obligations for non-exempt business-opportunity sellers. Those are different from the one-time franchise exemption notice. If the company cannot establish the exemption conditions, leave the track unresolved instead of budgeting only $25.')], 'A Texas sales-permission task with selling entity, exemption rationale, notice receipt and planned first-offer date.')
guide('washington','Washington: review offers, advertising and the operating relationship','Washington franchise registration, disclosure, advertising and relationship duties answer different questions.',['wa-registration','wa-disclosure-changes','wa-advertising','wa-relationship'],[
sec('Begin before a covered offer','RCW 19.100.020 addresses offering as well as selling. A registration or exemption review therefore belongs before a relevant offer, not merely before collecting the initial fee. Washington DFI gives the same starting instruction. The location of a future unit alone does not complete the jurisdiction analysis.'),
sec('Keep three clocks','The statute contains distinct initial-disclosure, revised-agreement and advertising provisions. Record each event separately rather than putting one “legal paperwork done” date in the launch schedule.',table={'headers':['Event','Reviewed requirement','Evidence'], 'rows':[['Initial disclosure','14 calendar days under RCW 19.100.080','Version delivered, recipient and delivery date'],['Specified unilateral material agreement change','7 calendar days; prospect-initiated negotiations treated separately','Revised document and negotiation record'],['Covered advertising publication','File true copy at least 7 days before publication unless shorter period allowed','Submitted version and planned channel/date']]}),
sec('The agreement needs an operating review','RCW 19.100.180 addresses good faith, purchasing restrictions, exclusive territory, termination and renewal. A national-account carve-out or mandatory supplier is an operating decision to review under those provisions, not just wording to copy from a home-market agreement.'),
sec('Fictional example: industrial maintenance','A Dutch brand promises an exclusive Washington territory while retaining national accounts. Its COO should define customer allocation, service responsibility, lead routing and revenue entitlement before final drafting. The exercise reveals what requires legal review; it does not decide whether any proposed term is enforceable.')], 'A Washington offer and advertising calendar, with a separate contract-operations review.')
guide('new-york','New York: build a renewal calendar around fiscal year end','New York’s current registration guide ties annual renewal submissions to 120 days after fiscal year end and gives advertising its own lead time.',['ny-renewal','ny-advertising'],[
sec('Use the company’s fiscal calendar','The Attorney General’s guide directs renewal submissions annually within 120 days after the franchisor’s fiscal year end. It distinguishes a timely pending renewal from an expired registration. If registration expires, the guide says no covered offers or sales within or from New York until the renewal is submitted and accepted for filing.'),
sec('The renewal is a management reporting task','The guide asks for the updated FDD, changes marked against the registered version, accountant consent and annual information about franchise sales, prices, credit terms and audited financial statements. Finance and sales operations both hold needed evidence. Start with an accountable owner and internal preparation dates, not a reminder on the last permissible day.'),
sec('Advertising has a separate schedule','The same guide calls for two copies of franchise advertising through NASAA FRED at least seven days before intended use. A timely renewal submission does not itself establish that the new recruitment campaign has met its advertising task.'),
sec('Fictional example: a UK training network','The franchisor’s fiscal year ends before the commercial team’s busiest recruitment period. The CFO records the year-end renewal deadline; the expansion director separately records campaign publication and advertising-submission dates. If the registration lapses, the team records the affected activity and the conditions for resuming it rather than assuming the website can continue selling.'),
sec('Output for the board pack',bullets=['Fiscal year-end date and calculated review deadline.','Named owner for audited statements and sales/credit information.','Registered and proposed FDD versions with change log.','Advertising inventory, submitted versions and intended-use dates.'])], 'A fiscal-year-based renewal checklist and a separate advertising register.')
guide('virginia','Virginia: establish the exemption before relying on it','Virginia requires registration or an applicable exemption; some exemption routes require a filing before an offer or sale.',['va-registration'],[
sec('Exempt is a conclusion supported by facts','Virginia SCC states that franchises offered or sold in Virginia must be registered or exempt. Its overview says exemptions may depend on franchisor experience, financial condition or the characteristics of the offer or grant. It directs readers to 21 VAC 5-110-75 for conditions and filing requirements.'),
sec('What an overseas management team should collect','Prepare the exact selling entity, relevant operating history, current financial statements, ownership chart, proposed buyer and transaction structure. Where a test concerns the franchisor, another group company’s trading history should not be substituted without establishing why the rule permits it.'),
sec('Fictional example: a French service group','The parent has a long operating history but a newly incorporated subsidiary will grant U.S. rights. The expansion director records both entities separately. The exemption question stays unresolved until the responsible reviewer maps the selected route to the correct entity, evidence and pre-offer filing conditions.'),
sec('A practical commitment gate',bullets=['Record the precise exemption provision being assessed.','Identify each condition and which entity/person must meet it.','Assign missing evidence and any required filing before the covered event.','Retain the filing acknowledgement or the reason a self-executing route applies.','Separately review disclosure, advertising and ongoing relationship obligations; this overview does not resolve them.'])], 'A Virginia registration-or-exemption memorandum with evidence and a pre-offer task.')
guide('oregon','Oregon: no franchise filing approval does not remove disclosure','Oregon DFR expressly distinguishes its disclosure and recordkeeping rules from states that approve franchise filings before a sale.',['or-disclosure'],[
sec('A narrow answer to a common question','Oregon DFR says it does not require franchisors to file franchise documents and obtain approval before a franchise sale. The same official page says disclosure must be provided at least 14 days before signing a contract or paying money. The absence of this filing process does not mean the offering is outside state law.'),
sec('Build the evidence trail','DFR also identifies complete books, records and franchise-sale details, including distribution of proceeds. A sales manager should retain which disclosure and agreements were sent, to whom, when, and what money was received. Finance should be able to reconcile proceeds to the transaction.'),
sec('Fictional example: an Irish IT services business','The team selects Oregon for customer interviews and later considers a branded operator. Its launch worksheet originally contains “registration: none” and no other sales-law tasks. The corrected worksheet records the narrow filing answer and adds the disclosure delivery, document-version and sale-record tasks. Customer procurement, tax nexus and employment remain separate questions.'),
sec('What this source does and does not establish','The page identifies ORS Chapter 650 and OAR Chapter 441 Division 325, complaint handling and a private civil remedy. It does not establish that every distribution, licensing, professional-services or business-opportunity model has the same outcome. State applicability still depends on the actual facts.',bullets=['Record the model and relevant Oregon connections.','Keep the 14-day disclosure clock separate from operational opening milestones.','Assign retention and proceeds-reconciliation responsibility.','Leave unresearched local and sector duties marked unknown.'])], 'An Oregon disclosure-and-recordkeeping task list, without an invented approval requirement.')
guide('wisconsin','Wisconsin: registration on receipt is not approval of the business','Wisconsin describes a same-day, non-merit registration process and a distinct 14-calendar-day disclosure duty.',['wi-registration','wi-disclosure','wi-amendment'],[
sec('Two independent prerequisites','Wisconsin DFI says a franchise must be registered no later than its first Wisconsin franchise sale. It describes registration as effective on receipt and expressly says Wisconsin is not a franchise merit-review state. A buyer should not read the registration receipt as validation of the model, projections or management team.'),
sec('Give disclosure time to run','The agency separately states that an FDD must be supplied 14 calendar days before the earlier of signing a binding franchise or other agreement or payment. Filing on receipt does not start or replace that delivery clock.'),
sec('Annual filing and material changes','DFI lists a $400 registration fee and one-year effectiveness. It says each franchise system needs a separate filing. Material-event amendments are due within 30 days, with a listed $200 fee, and do not restart the registration year. These amounts were checked against the agency FAQ on the review date and should be rechecked before payment.'),
sec('Fictional example: facilities and pest-control brands','A group sells two different franchise systems. Its company secretary should establish the separate filing scope, delivery versions and annual dates. A later corporate reorganization is evaluated as a possible material event rather than waiting automatically until next year.'),
sec('Separate the contract review','The FAQ also points to Wisconsin’s Fair Dealership Law. This guide does not resolve its applicability, exceptions, notice or cure requirements for a particular agreement. Preserve an independent contract review task even where the registration filing is straightforward.')], 'A Wisconsin filing, disclosure and amendment calendar with no claim of merit approval.')
guide('minnesota','Minnesota: registration and financial assurance are different tasks','Minnesota’s financial-assurance guidance explains why an initial franchise fee may be unavailable to fund immediate support.',['mn-registration','mn-assurance'],[
sec('Registration comes before covered offers and sales','Minnesota Statutes 80C.02 requires an effective registration before a covered offer or sale unless the franchise or transaction is exempt under 80C.03. The Department’s page directs electronic filings through ComOnline and describes a 12-month registration period from the commissioner’s order.'),
sec('Do not fund support with inaccessible fees','The financial-assurance guidance says the commissioner may require escrow, impoundment or deferral where adequate financial arrangements have not been demonstrated. It describes a surety-bond alternative and deferral of initial franchise fees until the franchisee has opened. A requested condition is part of the cash model; it is not proof that every applicant faces the same restriction.'),
sec('Fictional example: a German maintenance brand','The support office expects to pay a trainer and travel costs from an initial fee received at signature. If the applicable condition defers that fee until the operator opens, the support office needs another funding source during the intervening period. The CFO should model the dated receipts and payments under the actual condition rather than just recognising fee revenue.'),
sec('Prepare before the financial review',bullets=['Map each initial support obligation and when its cost is paid.','Identify committed capital that is available before any deferred or impounded fee release.','Keep the selected financial condition, agreement terms and release evidence.','Assign financial statements, filing forms and renewal dates to the company secretary and CFO.']),
sec('A disclosure detail still needs reconciliation','The registration page reproduces a seven-day state addendum statement. That is not a substitute for the federal 14-calendar-day period. The current Minnesota disclosure statute, rules and agency directions need a coordinated review before setting a transaction-specific date; the coverage register leaves that dimension unresolved.')], 'A Minnesota support-funding schedule that treats any financial-assurance condition explicitly.')
guide('hawaii','Hawaii: make the franchise filing package internally consistent','Hawaii’s official filing tips focus on matching entity names, funds calculations, notarization and accountant consent to the actual FDD.',['hi-filing'],[
sec('Use the current portal and document set','Hawaii DCCA directs franchise filers to the Securities Online Portal. Its helpful-tips document says to submit the required materials together for the relevant initial, renewal or amended category and pay the associated fee. This guide reviews document preparation, not the complete statutory registration or disclosure timing test.'),
sec('Cross-border details that can hold up a package','The tips call for Form C to be notarized by a U.S. notary and for the accountant consent to be signed and dated by a qualified CPA firm, reference the correct financial statements and address a guarantor’s statements where applicable. Verify the currently accepted notarization process and financial-statement directions before execution.'),
sec('Fictional example: a Singapore parent and U.S. subsidiary','The proposed franchisor is the U.S. subsidiary, but Form B uses the parent’s costs and the consent letter refers to different statements. The CFO and company secretary should reconcile each entity, obligation and statement period. A guarantee form with an incorrect name is a document discrepancy to resolve, not assurance of adequate support funding.'),
sec('Prepare a consistency sheet',table={'headers':['Record','Check','Owner'],'rows':[['Application and certification','Legal entity and FDD match','Company secretary'],['Costs/source of funds','Arithmetic and funding entity match obligations','CFO'],['Accountant consent','Correct statements, dates and guarantor','Finance/auditor'],['Seller forms','Actual persons offering rights','Sales operations'],['FDD and exhibits','All items, cover, receipts and agreements agree','Filing coordinator']]}),
sec('Keep the remaining analysis open','DCCA also links a 2023 interpretive order about statement currency. That order has not been fully reviewed in this batch. Do not infer that a financial-statement age, exemption or offer date has been approved merely because the package passes the consistency exercise.')], 'An entity-and-document consistency sheet for the Hawaii filing coordinator.')
guide('illinois','Illinois: prepare financial-assurance options without assuming one is mandatory','Illinois publishes franchise filing, escrow, guaranty, surety-bond and deposit forms. Choose documents from the actual requirement and review.',['il-forms'],[
sec('The official form set tells you what to prepare','The Illinois Attorney General’s Franchise Bureau administers franchise registration and publishes the application, costs/source-of-funds, seller, consent-to-service, guaranty and accountant-consent forms. The same page includes escrow, surety-bond and deposit documents. Their availability is evidence of published processes, not evidence that every applicant must use every form.'),
sec('Separate financial capacity from form completion','An overseas CFO should identify the selling entity’s own commitments and resources, any proposed guarantor and which entity will pay training and opening support costs. The team then matches requested assurance to actual documents and the cash model. The website does not approve a guarantor or predict an examiner’s decision.'),
sec('Fictional example: initial support funded by the parent','A Swedish service brand expects its parent to fund training while a U.S. subsidiary signs franchises. The company secretary should not merely attach the parent’s accounts. Prepare an ownership chart, support-cost schedule, proposed commitment and correct statement/consent references so the filing reviewer can assess the chosen structure.'),
sec('Useful preparation checklist',bullets=['Current proposed FDD and agreements for the exact selling entity.','Initial obligations, timing and source-of-funds schedule.','Auditor consent referring to the correct financial statements.','Actual requested assurance and supporting agreement/form.','Separate review of offer timing, exemptions, advertising, relationship and broker duties.']),
sec('Coverage limit','The current statutory initial timing, fee and exemption tests have not been fully source-verified in this batch. They remain open requirements in the matrix. This preparation guide is not a statement that a filing is complete or an offering may start.')], 'An Illinois finance-and-document preparation package with open statutory questions recorded.')
guide('maryland','Maryland: an exemption can preserve disclosure and notice duties','Maryland registration exemptions have their own conditions; specified routes preserve earlier disclosure events.',['md-registration','md-exempt-disclosure','md-advertising'],[
sec('Begin with the actual offer','Business Regulation 14-214 requires registration before a covered offer, including advertising, or sale, subject to stated exceptions. COMAR 02.02.08.10 then supplies particular exemption routes. An exemption from registration is not a universal exemption from the rest of the franchise law.'),
sec('Identify the selected exemption and its clock','For specified exemptions in paragraphs D–G, COMAR states that absent a contrary order the offering circular and agreements must be delivered at the earlier of the first personal meeting or ten business days before signing or payment. Specified routes also have notice conditions. This first-meeting trigger shows why a universal “we can disclose fourteen days before payment” rule is inadequate.'),
sec('Reconcile the source versions','The regulation uses legacy UFOC terminology and references alongside current franchise practice. The task is to reconcile the applicable statute, regulation and current agency instructions for the selected exemption. This page records the rule’s explicit language and leaves transaction-specific application conditional; it does not silently discard the earlier trigger.'),
sec('Fictional example: a Belgian technical-services group','The team assumes a large-company exemption permits an immediate in-person recruitment meeting. Its launch planner instead records the proposed meeting, buyer facts, selected exemption and disclosure/notice prerequisites. A responsible reviewer confirms the route and timing before the relevant commitment.'),
sec('Advertising stays on the work list','COMAR .09 calls for a copy of covered advertising at least five days before anticipated initial use. Maintain an inventory of the material, exact version, sponsor, channel and first-use date. Keep advertising review separate from the exemption evidence.')], 'A Maryland exemption checklist with first-meeting, notice and advertising dates.')
guide('michigan','Michigan: annual notice filing and disclosure use different clocks','Michigan’s notice-only process does not remove state disclosure requirements or turn an FDD into an approved document.',['mi-notice','mi-disclosure'],[
sec('File the notice before the covered activity','MCL 445.1507a requires an annual notice before offering or selling in the state. The agency describes a Notice of Intent, a $250 fee and annual repetition. It also says it does not review FDD compliance. Filing is evidence of a notice; it is not a legal opinion on the documents.'),
sec('Count business days separately','MCL 445.1508 requires disclosure, the prescribed Michigan notice and proposed agreements at least ten business days before binding agreement or consideration, whichever occurs first. The federal 14-calendar-day disclosure requirement is independent. The team should satisfy both applicable clocks, accounting for the actual dates, rather than converting ten business days into a fixed calendar-day count.'),
sec('The state notice is substantive','Section 8 describes a Michigan disclosure page and prohibited-term notice. It says the existence of a notice on file does not constitute approval, recommendation or endorsement. Record the correct state page and the agreement version delivered; do not reduce the task to sending a generic home-market brochure.'),
sec('Fictional example: a Thai training business','A manager plans to accept a partner deposit after a long holiday weekend. The company secretary records the delivery date and separately calculates federal calendar days and Michigan business days for the planned payment and signature events. If any assumption about delivery or holiday treatment is unresolved, the date remains pending.'),
sec('Evidence to retain',bullets=['Filed annual notice and its anniversary.','Delivered FDD, Michigan page and all proposed agreements.','Recipient and delivery evidence.','Independent calendar and business-day calculations.','Changes to the proposed agreement and who initiated them.'])], 'A Michigan notice record and dual-clock disclosure schedule.')
guide('indiana','Indiana: registration by notification still comes before covered offers','Indiana calls its franchise registration a notice filing process without merit review; exemption facts and annual dates still matter.',['in-notification'],[
sec('Understand what the filing establishes','Indiana’s Securities Division says a franchisor must register before offering or selling unless exempt. It describes initial effectiveness on receipt if no stop order is in effect, a one-year period and a notice filing process without merit review. A filing receipt therefore does not substantiate commercial promises or certify the franchise.'),
sec('The exemption is state-specific','The agency describes de minimis, large-net-worth, franchisee-sale and rule/order routes and says the burden of establishing an exemption rests with the claimant. It calls the described exemptions self-executing and offers an optional determination-letter procedure. Do not import a federal or another state’s exemption test.'),
sec('Fictional example: a Danish industrial-service pilot','A group investigates one Indiana operator and assumes that “one licence” is universally exempt. The correct preparation is to identify the specific Indiana route, sales history, related transactions and all conditions. The federal franchise rule and any relevant other states are analysed separately. A narrow state exemption is not one free franchise in every jurisdiction.'),
sec('Build a filing-and-renewal owner','The agency lists a $500 initial fee, current FDD, seller disclosures, consent to service and supplemental materials. It says renewal must be filed no later than expiry; a lapse requires an initial filing and fee. The company secretary should retain exact filing/expiry dates and reconcile the entity and document versions.'),
sec('What remains unresolved',bullets=['Precise transaction and exemption applicability.','Independent disclosure timing and agreement changes.','Advertising and ongoing relationship rules.','Operating licences, customer bid conditions and local premises requirements.'])], 'An Indiana registration-or-exemption record with an annual renewal owner.')
guide('north-dakota','North Dakota: update renewal timing and remove outdated addendum assumptions','North Dakota’s current agency page gives a pre-expiry renewal deadline and a specific April 2026 change to its FDD addendum practice.',['nd-renewal'],[
sec('Set the renewal work before the expiry date','The agency directs renewal no later than fifteen business days before registration expires unless the commissioner waives the period. It describes a twelve-month registration period unless an order or rule says otherwise. A same-day expiry reminder does not provide the required preparation window.'),
sec('A changed form requirement is not deregulation','The page expressly states that from April 1, 2026 a state-specific FDD addendum is no longer required. This is a narrow document change. The registration, financial review, disclosure and amendment tasks do not disappear. A source change should flag dependent pages and templates for editorial review rather than automatically rewriting every obligation.'),
sec('Fictional example: a Netherlands maintenance network','The team reuses last year’s filing checklist. The coordinator finds the agency’s dated addendum notice, marks that template item for revision and preserves the reviewed prior version. The renewal owner separately checks the FDD, changes marked against the prior version, accountant consent, seller forms and advertising not previously filed.'),
sec('Assign the evidence',bullets=['Effective registration and expiry dates from the actual record.','Business-day renewal deadline with any written waiver.','Current filing instructions and a reviewed checklist revision.','Financial-assurance condition if applicable.','Material-change reporting owner and document-version log.']),
sec('Do not repeat the agency’s national state count','The source contains a broad count of registration states. This site does not reuse it as a national legal classification. Notice filing, merit review, exemptions and relationship laws are recorded independently for each jurisdiction.')], 'A current North Dakota renewal checklist and traceable April 2026 template revision.')
guide('rhode-island','Rhode Island: registration and exemption notices have different anniversaries','Rhode Island’s active regulation measures registration from the initial effective date and exemption notices from receipt.',['ri-registration'],[
sec('Two annual dates can differ','R.I. Gen. Laws 19-28.1-5 prohibits covered franchise offers or sales without registration or exemption. Active regulation 230-RICR-50-10-1.4 gives registration a 365-calendar-day period from its initial effective date. It gives an exemption a 365-day period from receipt of the notice. Filing, receipt and effectiveness are distinct dates.'),
sec('Do not treat a fractional franchise as a label','The active regulation also sets out a fractional-franchise route with multiple conditions involving existing business experience, location, similarity, expected revenue share and control. It contains state-specific filing language. Those provisions need a coordinated review before relying on the route; a federal fractional exemption is not the answer to the state question.'),
sec('Fictional example: a UK technical-service add-on','An established Rhode Island operator wants to add a branded service to its existing business. The brand records the operator’s existing business, experience, site, projected first-year mix and control facts. It leaves the exemption conditional until every relevant condition and required filing has been reviewed.'),
sec('The company secretary’s calendar',bullets=['Select registration or the exact exemption route.','Record application submission, actual receipt and effective date separately.','Identify which date controls the anniversary.','Preserve the reviewed rule version and exemption evidence.','Assign independent disclosure, advertising and operating-law review.'])], 'A Rhode Island filing log with the correct anniversary and conditional exemption analysis.')
guide('south-dakota','South Dakota: notice filing does not mean no filing','South Dakota’s franchise notice law has pre-offer, completeness, annual renewal and continuing financial-reporting dimensions.',['sd-notice','sd-advertising'],[
sec('The statute calls it notice filing','SDCL 37-5B-4 prohibits a covered offer or sale unless properly notice filed or exempt. Section 37-5B-5 describes a complete filing with the FDD, application, consent to service and $250 initial fee. It generally becomes effective on receipt, subject to completeness and order/injunction provisions. Do not replace the actual receipt with an assumed mailing date.'),
sec('Keep annual and financial events separate','The statute generally gives one year from receipt unless a different period is prescribed. It lists a $150 renewal fee and treats late filings as initial filings. It also requires notice within fifteen days after an auditor reaches the specified going-concern conclusion after effectiveness. The annual calendar will not catch every material financial event.'),
sec('Advertising filing and truthful advertising are different','SDCL 37-5B-23 says advertisements need not be filed unless the director requests them. It also permits action against misleading advertising. “No routine advertising filing” should therefore be recorded narrowly; it does not support unsubstantiated revenue or profitability claims.'),
sec('Fictional example: a German commercial-cleaning network','The CFO flags an auditor going-concern conclusion while the sales team is recruiting partners. The compliance owner records the conclusion date, the separate reporting task and any actual financial-assurance condition. The commercial team preserves advertising versions and substantiation rather than assuming a notice receipt approves the claims.'),
sec('Commitment evidence',bullets=['Complete filed package and actual receipt/effectiveness.','Exemption route and conditions if claimed.','Annual expiry and internal renewal date.','Auditor-event reporting owner.','Advertising evidence and any director request or order.'])], 'A South Dakota notice calendar and event-driven financial reporting task.')
# Distinct issue guides reuse canonical rule records rather than duplicating facts.
guide('new-york-advertising','When should a New York franchise advertisement be submitted?','Treat a recruitment campaign as a versioned filing task with a seven-day lead time.',['ny-advertising'],[
sec('The direct answer','New York’s current Attorney General guide requires two copies of advertising used in offering or selling franchises, submitted through NASAA FRED at least seven days before intended use. Identify the exact material, channel, sponsor and date before starting the clock.'),
sec('Fictional campaign handoff','A French training brand’s marketing agency edits a recruitment landing page after counsel reviews a PDF. The operations team should compare the actual proposed advertisement with the submitted version and record whether the change requires another review or filing. An approval of a different version does not establish the status of the live one.'),
sec('Build a campaign evidence record',bullets=['Campaign ID and exact document/screenshot version.','Targeted audience and jurisdiction facts.','Intended first-use date.','Submission copies, date and receipt.','Responsible editor and source of any earnings claim.','Final check against the version scheduled for publication.']),
sec('Limits','This is the advertising submission rule described by the agency, not an automated decision about whether every communication is a franchise advertisement. Registration, exemption and disclosure remain distinct.')], 'A version-controlled campaign record.',family='state-issue',path='/states/new-york/franchise-advertising/')
guide('michigan-disclosure-timing','How do Michigan business days interact with federal disclosure timing?','Keep the two clocks visible rather than converting them to a universal waiting period.',['mi-disclosure'],[
sec('Keep both requirements','Michigan section 445.1508 specifies ten business days before the earlier binding agreement or consideration, with the disclosure statement, prescribed notice and proposed agreements. The federal Rule has its separate 14-calendar-day disclosure requirement. One calculation must not silently replace the other.'),
sec('Fictional scheduling problem','A Singapore service brand delivers documents shortly before a holiday period and plans a partner deposit two weeks later. The scheduler records the actual delivery method and receipt facts, the federal calendar calculation and a separate Michigan business-day calculation. The planned payment and signature each remain blocked until the relevant prerequisites are established.'),
sec('A timing worksheet',table={'headers':['Input','Evidence required'],'rows':[['Disclosure event','Version, recipient, delivery/receipt facts'],['Michigan notice','Required state page included'],['Agreements','Every proposed agreement and changes'],['Calendar calculation','Federal calendar-day start and event'],['Business-day calculation','Michigan day-count method and holidays reviewed'],['Commitment','Earliest signature or payment event']]}),
sec('Record uncertainty','This worksheet does not determine a legal delivery date or calculate holiday rules automatically. Unresolved receipt, amendment or negotiation facts should remain named questions, not a green permission indicator.')], 'A dual-clock disclosure worksheet.',family='state-issue',path='/states/michigan/franchise-disclosure-timing/')
guide('minnesota-support-funding','Can Minnesota initial franchise fees fund pre-opening support?','Use the actual financial-assurance condition to model when money becomes available.',['mn-assurance'],[
sec('The answer depends on the condition','Minnesota’s published guidance describes escrow, impoundment, surety-bond and fee-deferral arrangements where the financial review requires assurance. If the applicable arrangement delays receipt or release until opening or another condition, the same fee cannot fund earlier cash costs unless separate available capital bridges the timing.'),
sec('Fictional cash illustration','Assume, solely for planning, that a brand must pay $12,000 for training travel and wages in month one while an initial fee becomes available in month three. The pre-opening funding task is the dated $12,000 outflow and any other actual outflows, reduced only by committed receipts available in those months. Do not count both an expense and an identical arbitrary reserve as two different costs.'),
sec('What the CFO should document',bullets=['Exact financial condition and its release trigger.','Support obligations with payment dates.','Cash actually available before release.','Alternative funding evidence, cost and constraints.','Release evidence and responsible person.','Downside opening-date assumption.']),
sec('Scope','The illustrative amount is invented and is not a Minnesota fee or required reserve. This guide does not predict an examiner’s condition. Use the actual order/agreement and reviewed guidance in the cash model.')], 'A dated support-funding bridge.',family='state-issue',path='/states/minnesota/franchise-support-funding/')
# Unpublished backlog records are real scope records and never counted as public guides.
covered={g['jurisdictions'][0] for g in guides if len(g['jurisdictions'])==1}
for state in states:
 if state['name'] in covered:continue
 blocked=state['name']=='California'
 guides.append(dict(id='state-draft-'+state['slug'],path='/states/'+state['slug']+'/',title=state['name']+': franchise and operating research',description='Unpublished research record; evidence and original jurisdiction-specific explanation required.',family='state',topic='sales-disclosure',jurisdictions=[state['name']],status='blocked' if blocked else 'draft',lastReviewed=None,reviewStatus='Not yet substantively reviewed',readMinutes=0,ruleIds=[],sections=[],sourceIds=state['sourceIds'],nextStage=1,practicalOutput='A reviewed jurisdiction-specific commitment checklist, pending research.',limitations=['Not published or included in the sitemap.']+(['Official primary sources denied access (403). Reacquire current full text, including financial assurance and 2026 broker obligations, before publication.'] if blocked else [])))
